select v.id, c.id, 'label_pair', jsonb_build_object('source', 'ris_v13')
  from semantic_private.presumed_terms v, semantic_private.presumed_terms c
 where v.normalized_label = '#celebration' and v.family = 'work'
   and c.normalized_label = 'celebration' and c.family = 'work'
   and v.id <> c.id and v.canonical_term_id is null
   and coalesce(c.canonical_term_id, c.id) <> v.id;
