do $$
declare
  n integer;
begin
  select count(*) into n from semantic_private.presumed_terms;
  raise notice '0307: % terms in the dictionary', n;
  select count(*) into n from semantic_private.presumed_terms
   where english_label is not null;
  raise notice '0307: % carry an English label', n;
  select count(*) into n from semantic_private.presumed_terms
   where canonical_term_id is not null;
  raise notice '0307: % defer to a canonical', n;
  select count(*) into n from semantic_private.presumed_term_relations;
  raise notice '0307: % relations recorded', n;
end;
$$;

